function SchoolPortalShell({company,user,page,setPage,onLogout,children}){
  useEffect(()=>applyBrowserBranding(company),[company?.id,company?.name,company?.logoData,company?.faviconData,JSON.stringify(readGlobalBranding())]);
  const[profileOpen,setProfileOpen]=useState(false);
  const profileRef=useRef();
  useEffect(()=>{const close=e=>{if(profileRef.current&&!profileRef.current.contains(e.target))setProfileOpen(false)};document.addEventListener('mousedown',close);return()=>document.removeEventListener('mousedown',close)},[]);
  const heading=page==='map'?{title:'Live Map',subtitle:'Track school buses, routes, students and stops in real time.'}:{title:'School Bus',subtitle:'Safe journeys, clear updates'};
  const schoolName=String(company?.schoolName||company?.name||'School Bus').trim()||'School Bus';
  return <div className="schoolPortalShell"><aside className="schoolPortalSidebar"><div className="schoolPortalBrand"><img src="/masar-tracking-logo.png" alt="Masar Tracking"/></div><nav aria-label="School bus navigation">{SCHOOL_PORTAL_NAV.map(([key,label,Icon])=><button key={key} className={page===key?'active':''} onClick={()=>setPage(key)}><Icon/><span>{label}</span></button>)}</nav><div className="schoolPortalBuilding" aria-hidden="true"><img src="/assets/school-campus-blue.svg" alt=""/></div><button className="schoolPortalLogout" onClick={onLogout}><LogOut/><span>Logout</span></button></aside><header className="schoolPortalTop"><div className="schoolPortalTitle"><b title={schoolName}>{schoolName}</b><span>{heading.title==='Live Map'?'Live Map':'School Bus · Safe journeys, clear updates'}</span></div><div className="schoolPortalTopActions"><button className="schoolPortalNotice" type="button" aria-label="Open attendance notifications" title="Open attendance" onClick={()=>setPage('attendance')}><Bell/></button><div className="schoolPortalProfile" ref={profileRef}><button type="button" onClick={()=>setProfileOpen(value=>!value)}><span className="schoolPortalAvatar">{(user?.name||company?.name||'M')[0]}</span><span><b>{user?.name||company?.adminName||'Company admin'}</b><small>{company?.name||'School portal'}</small></span><ChevronDown/></button>{profileOpen&&<div className="schoolPortalMenu"><button type="button" onClick={onLogout}><LogOut/>Logout</button></div>}</div></div></header><main className="schoolPortalMain">{children}</main></div>
}

function parseSchoolCsv(text){const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const ch=text[i],next=text[i+1];if(ch==='"'&&quoted&&next==='"'){cell+='"';i++;continue}if(ch==='"'){quoted=!quoted;continue}if(ch===','&&!quoted){row.push(cell.trim());cell='';continue}if((ch==='\n'||ch==='\r')&&!quoted){if(ch==='\r'&&next==='\n')i++;row.push(cell.trim());cell='';if(row.some(value=>value!==''))rows.push(row);row=[];continue}cell+=ch}if(cell!==''||row.length){row.push(cell.trim());if(row.some(value=>value!==''))rows.push(row)}if(!rows.length)return[];const headers=rows.shift().map((value,index)=>index===0?value.trim().replace(/^\uFEFF/,''):value.trim());return rows.map(values=>Object.fromEntries(headers.map((header,index)=>[header,values[index]??''])))}
function schoolCsvBody(columns,rows=[]){return '\uFEFF'+[columns.map(column=>csv(column.label)).join(','),...rows.map(row=>columns.map(column=>csv(row[column.key]??'')).join(','))].join('\r\n')}
function schoolCsvValue(row,column){return typeof column.value==='function'?column.value(row):row?.[column.key]??''}
function SchoolCsvActions({entity,rows,columns,onImport,toast,showTemplate=true,showImport=true,showExport=true}){
  const inputRef=useRef(),[busy,setBusy]=useState(false),[preview,setPreview]=useState(null);
  const downloadTemplate=()=>fileDownload(entity+'-template.csv',schoolCsvBody(columns),'text/csv;charset=utf-8');
  const exportData=()=>{const exportRows=rows.map(row=>Object.fromEntries(columns.map(column=>[column.key,schoolCsvValue(row,column)]))),labels=Object.fromEntries(columns.map(column=>[column.key,column.label]));requestExport(entity+'-export',exportRows,{formats:['pdf','csv','xlsx','html'],labels})};
  const chooseFile=()=>inputRef.current?.click();
  const onFile=async event=>{const file=event.target.files?.[0];event.target.value='';if(!file)return;setBusy(true);try{const imported=parseSchoolCsv(await file.text());if(!imported.length){toast('The CSV file is empty.');return}setPreview({fileName:file.name,rows:imported})}catch(error){toast(error.message||'Unable to read CSV file.')}finally{setBusy(false)}};
  const commit=async()=>{if(!preview)return;setBusy(true);try{const saved=await onImport(preview.rows);if(saved===false)throw Error('The records were not saved. Please check your connection and try again.');toast(preview.rows.length+' '+entity+' records imported.');setPreview(null)}catch(error){toast(error.message||'Unable to import CSV file.')}finally{setBusy(false)}};
  const headers=preview?.rows?.[0]?Object.keys(preview.rows[0]):[];
  return <><div className="schoolPortalCsvActions">{showTemplate&&<button type="button" onClick={downloadTemplate}><Download/>Template</button>}{showImport&&<button type="button" onClick={chooseFile} disabled={busy}><Upload/>{busy?'Reading…':'Import CSV'}</button>}{showExport&&<button type="button" onClick={exportData}><Download/>Export</button>}<input ref={inputRef} type="file" accept=".csv,text/csv" onChange={onFile} hidden/></div>{preview&&<div className="schoolCsvPreviewOverlay"><section className="schoolCsvPreview" role="dialog" aria-modal="true" aria-label="Review CSV import"><header><div><h2>Review {entity} import</h2><p>{preview.fileName} · {preview.rows.length} rows ready to check</p></div><button type="button" aria-label="Close" onClick={()=>setPreview(null)}><X/></button></header><div className="schoolCsvPreviewTable"><table><thead><tr>{headers.map(header=><th key={header}>{header}</th>)}</tr></thead><tbody>{preview.rows.slice(0,5).map((row,index)=><tr key={index}>{headers.map(header=><td key={header}>{row[header]||'—'}</td>)}</tr>)}</tbody></table>{preview.rows.length>5&&<p>Showing the first 5 rows. All {preview.rows.length} rows will be imported.</p>}</div><footer><button type="button" onClick={()=>setPreview(null)}>Cancel</button><button type="button" className="primary" disabled={busy} onClick={commit}><Upload/>Import {preview.rows.length} rows</button></footer></section></div>}</>
}
