function SchoolAttendanceForm({company,children,vehicles,store,setStore,onSaved,onClose,toast,correctedBy}){const[d,setD]=useState({childId:'',eventType:'boarded',scannedAt:new Date().toISOString().slice(0,16),reason:''});const f=(key,value)=>setD(current=>({...current,[key]:value}));const child=children.find(row=>String(row.id)===String(d.childId)),vehicle=vehicles.find(row=>String(row.id)===String(child?.vehicleId));const save=async e=>{e.preventDefault();if(!child){toast('Choose a child first.');return}if(!d.reason.trim()){toast('Enter a reason for this manual attendance correction.');return}const row={id:id(),companyId:company.id,childId:child.id,childName:child.name,vehicleId:vehicle?.id||child.vehicleId||null,vehicleName:vehicle?.name||child.vehicleName||'',eventType:d.eventType,scannedAt:new Date(d.scannedAt).toISOString(),source:'manual_correction',verificationMethod:'Manual correction',correctionReason:d.reason.trim(),correctedBy:correctedBy||'School administrator',createdAt:new Date().toISOString()};if(!await setStore(addRow(store,'schoolScans',row)))return;toast('Manual attendance correction saved with its reason.');onSaved()};return <form onSubmit={save} className="formGrid schoolFormGrid"><Field label="Child *" wide><select required value={d.childId} onChange={e=>f('childId',e.target.value)}><option value="">Choose child</option>{children.map(row=><option key={row.id} value={row.id}>{row.name}{row.vehicleName?` · ${row.vehicleName}`:''}</option>)}</select></Field><Field label="Verified event *"><select value={d.eventType} onChange={e=>f('eventType',e.target.value)}><option value="boarded">Boarded</option><option value="alighted">Got off</option></select></Field><Field label="Event date and time"><input type="datetime-local" value={d.scannedAt} onChange={e=>f('scannedAt',e.target.value)}/></Field><Field label="Correction reason *" wide><input required value={d.reason} onChange={e=>f('reason',e.target.value)} placeholder="Why is this attendance record being added?"/></Field>{child&&<div className="schoolPortalFormNote wide"><CheckCircle2/> {child.name} · {vehicle?.name||child.vehicleName||'Bus not assigned'} · This adds an auditable correction and does not send a parent notification.</div>}<div className="modalActions wide"><button type="button" onClick={onClose}>Cancel</button><button className="primary" disabled={!child}><Save/>Save correction</button></div></form>}
function SchoolMultiBusSelect({vehicles,value=[],onChange}){const[open,setOpen]=useState(false),root=useRef(null),selected=(value||[]).map(String);useEffect(()=>{if(!open)return;const outside=event=>{if(!root.current?.contains(event.target))setOpen(false)},escape=event=>{if(event.key==='Escape')setOpen(false)};document.addEventListener('pointerdown',outside);document.addEventListener('keydown',escape);return()=>{document.removeEventListener('pointerdown',outside);document.removeEventListener('keydown',escape)}},[open]);const toggle=vehicleId=>{const key=String(vehicleId);onChange(selected.includes(key)?selected.filter(id=>id!==key).map(Number):[...selected,key].map(Number))};return <div className="schoolMultiBusSelect" ref={root}><button type="button" className="schoolMultiBusTrigger" aria-expanded={open} aria-controls="school-multi-bus-options" onClick={()=>setOpen(value=>!value)}><span>{selected.length?`${selected.length} bus${selected.length===1?'':'es'} selected`:'Select buses'}</span><ChevronDown/></button>{open&&<div id="school-multi-bus-options" className="schoolMultiBusOptions" role="group" aria-label="Assigned buses">{vehicles.length?vehicles.map(vehicle=><label key={vehicle.id} className="schoolMultiBusOption"><input type="checkbox" checked={selected.includes(String(vehicle.id))} onChange={()=>toggle(vehicle.id)}/><span>{vehicle.name} · ID {vehicle.id}</span></label>):<div className="schoolMultiBusEmpty">No buses available</div>}</div>}</div>}
