function SchoolRfidForm({initial={},cards=[],children=[],company,store,setStore,onSaved,onClose,toast}){
  const[d,setD]=useState({tagNumber:initial.tagNumber||initial.rfidIdentifier||'',personnelNumber:initial.personnelNumber||'',status:initial.status||'Active'}),[error,setError]=useState('');
  const f=(key,value)=>setD(current=>({...current,[key]:value}));
  const normalizeTag=value=>String(value||'').trim().toUpperCase().replace(/\s+/g,'');
  const save=async event=>{
    event.preventDefault();setError('');
    const tagNumber=normalizeTag(d.tagNumber),normalized=tagNumber,personnelNumber=String(d.personnelNumber||'').trim();
    if(!normalized){setError('Enter the RFID tag number.');return}
    if(!personnelNumber){setError('Enter the RFID personnel number.');return}
    const original=normalizeTag(initial.tagNumber||initial.rfidIdentifier),existing=(store.schoolRfidCards||[]).find(card=>String(card.companyId)===String(company.id)&&(String(card.id)===String(initial.id)||normalizeTag(card.tagNumber||card.rfidIdentifier)===original));
    if(cards.some(card=>normalizeTag(card.tagNumber||card.rfidIdentifier)===normalized&&normalizeTag(card.tagNumber||card.rfidIdentifier)!==original)){setError('This RFID tag number already exists.');return}
    if(children.some(child=>normalizeTag(child.rfidIdentifier)===normalized&&normalized!==original)){setError('This RFID tag is already assigned.');return}
    const card={...(existing||{}),id:existing?.id||initial.id||id(),companyId:company.id,tagNumber,personnelNumber,status:d.status==='Inactive'?'Inactive':'Active',updatedAt:new Date().toISOString()},allCards=[...(store.schoolRfidCards||[])],index=allCards.findIndex(row=>String(row.id)===String(card.id));if(index<0)allCards.push(card);else allCards[index]=card;
    let next={...store,schoolRfidCards:allCards};
    const assigned=children.filter(child=>normalizeTag(child.rfidIdentifier)===original&&original);
    for(const child of assigned){const updated={...child,rfidIdentifier:tagNumber,metadata:{...(child.metadata||{}),rfidStatus:card.status,rfidPersonnelNumber}};next=updateRow(next,'schoolChildren',child.id,updated)}
    if(!await setStore(next))return;
    const results=await Promise.allSettled(assigned.map(child=>{const serverId=child.serverId||(Number.isSafeInteger(Number(child.id))?Number(child.id):null);return serverId?api.updateSchoolChild(serverId,{companyId:company.id,name:child.name,grade:child.grade,className:child.className,rfidIdentifier:tagNumber,metadata:{...(child.metadata||{}),rfidStatus:card.status,rfidPersonnelNumber}}):Promise.resolve()}));
    toast(results.some(result=>result.status==='rejected')?'RFID card saved on this PC. Server sync needs attention.':'RFID card saved.');onSaved();
  };
  return <form onSubmit={save} className="formGrid schoolFormGrid">{error&&<div className="formError wide">{error}</div>}<Field label="RFID tag number *" wide><input required value={d.tagNumber} onChange={event=>f('tagNumber',event.target.value)} placeholder="Enter or scan the card UID" autoFocus/></Field><Field label="RFID personnel number *"><input required value={d.personnelNumber} onChange={event=>f('personnelNumber',event.target.value)} placeholder="Student or staff number"/></Field><Field label="Status"><select value={d.status} onChange={event=>f('status',event.target.value)}><option>Active</option><option>Inactive</option></select></Field><div className="schoolPortalFormNote wide"><Radio/> Cards are registered here first. Assign an active, unassigned card from the child form.</div><div className="modalActions wide"><button type="button" onClick={onClose}>Cancel</button><button className="primary"><Save/>{initial.id?'Save card':'Add RFID card'}</button></div></form>
}

