function SchoolPortalCount({value}){
  const target=Math.max(0,Number(value)||0),[display,setDisplay]=useState(0),current=useRef(0);
  useEffect(()=>{
    const start=current.current;
    if(start===target)return;
    if(window.matchMedia?.('(prefers-reduced-motion: reduce)').matches){current.current=target;setDisplay(target);return}
    let frame=0,startedAt=0;
    const tick=now=>{
      if(!startedAt)startedAt=now;
      const progress=Math.min(1,(now-startedAt)/850),eased=1-Math.pow(1-progress,3),next=Math.round(start+(target-start)*eased);
      current.current=next;setDisplay(next);
      if(progress<1)frame=requestAnimationFrame(tick);else{current.current=target;setDisplay(target)}
    };
    frame=requestAnimationFrame(tick);
    return()=>cancelAnimationFrame(frame);
  },[target]);
  return <b aria-label={target.toLocaleString('en-US')}>{display.toLocaleString('en-US')}</b>;
}

