function schoolVehicleRow(vehicle,company){const deviceId=vehicle.traccar_device_id,device={id:deviceId,name:vehicle.name,uniqueId:vehicle.imei,status:vehicle.connection_status||vehicle.device_status,lastUpdate:vehicle.last_update,currentDriver:vehicle.current_driver},hasPosition=vehicle.latitude!=null&&vehicle.longitude!=null&&Number.isFinite(Number(vehicle.latitude))&&Number.isFinite(Number(vehicle.longitude)),position=hasPosition?{deviceId,latitude:Number(vehicle.latitude),longitude:Number(vehicle.longitude),altitude:vehicle.altitude??null,course:vehicle.course??null,speed:vehicle.speed_kph==null?null:Number(vehicle.speed_kph)/1.852,valid:vehicle.position_valid,serverTime:vehicle.position_time||vehicle.last_update,deviceTime:vehicle.device_time,fixTime:vehicle.fix_time,address:vehicle.address||'',attributes:{...(vehicle.attributes||{}),ignition:vehicle.ignition,motion:vehicle.motion}}:null,local=(loadStore().vehicles||[]).find(row=>String(row.id)===String(vehicle.id))||{},state=stateOf(device,position,company?.settings?.offlineMinutes||300,company?.settings?.noSignalMinutes||5,company?.settings?.untrackedMinutes);return{id:Number(vehicle.id),companyId:Number(vehicle.company_id),deviceId,name:vehicle.name||'Vehicle',plate:vehicle.plate_number||'',imei:vehicle.imei||'',...(local||{}),position,state,speed:kmh(position),device,currentDriver:vehicle.current_driver||null,driverName:vehicle.current_driver?.name||vehicle.metadata?.driverName||'—',category:vehicle.metadata?.category||'Bus',protocol:vehicle.protocol||'GT06',deviceModel:vehicle.device_model||'',liveAccess:vehicle.live_access!==false,accessStatus:vehicle.access_status||'active',accessMessage:vehicle.access_message||'',expired:vehicle.expired===true};}

export function SchoolPortalApp(){
  const[store,setStoreRaw]=useState(()=>ensureCompany(loadStore())),[authUser,setAuthUser]=useState(null),[authChecked,setAuthChecked]=useState(false),[fleetLoaded,setFleetLoaded]=useState(false),[page,setPageRaw]=useState(()=>{const part=window.location.pathname.split('/').filter(Boolean).pop();return ['children','buses','routes','branches','rfid','attenders','attendance','drivers','parents','coordinators','map','reports','settings'].includes(part)?part:'dashboard'}),[toast,setToast]=useState(''),[fleetVehicles,setFleetVehicles]=useState([]),[selectedVehicle,setSelectedVehicle]=useState(null);
  const company=store.companies[0],version=useRef(0),saveQueue=useRef(Promise.resolve());
  const applyRemote=(co,remote)=>{version.current=Number(remote?.version)||0;setStoreRaw(prev=>{const fresh=ensureCompany(loadStore()),base=preserveLocalSchoolState({...fresh,...(remote?.data||{}),headerBanner:remote?.headerBanner||null},fresh);return saveStore({...base,companies:co?[{...(base.companies?.[0]||{}),...(co.metadata||{}),...(base.companyProfile||{}),id:Number(co.id),name:base.companyProfile?.name||co.name,email:base.companyProfile?.email||co.email,status:co.status,settings:{...(base.companies?.[0]?.settings||{}),...(base.companyProfile?.settings||{}),...(base.companyPreferences||{})}}]:base.companies})})};
  const hydrate=async user=>{if(user?.role!=='school_admin'||user?.metadata?.schoolAdmin!==true){setAuthToken('');throw Error('school_role_required')}try{const[co,remote]=await Promise.all([api.company(),api.companyState()]);applyRemote(co,remote);setAuthUser(user)}catch(error){setAuthToken('');setAuthUser(null);throw error}};
  useEffect(()=>{if(!authToken()){setAuthChecked(true);return}Promise.all([api.me(),api.company(),api.companyState()]).then(([user,co,remote])=>{if(user.role!=='school_admin'||user?.metadata?.schoolAdmin!==true)throw Error('school_role_required');applyRemote(co,remote);setAuthUser(user)}).catch(()=>{setAuthToken('');setAuthUser(null)}).finally(()=>setAuthChecked(true))},[]);
  useEffect(()=>{if(!authUser)return;let alive=true,stopStream=()=>{},timer=null;const apply=rows=>{if(!alive||!Array.isArray(rows))return;const mapped=rows.filter(row=>String(row.company_id)===String(company.id)).map(row=>schoolVehicleRow(row,company));setFleetVehicles(mapped);setFleetLoaded(true);setSelectedVehicle(current=>current?mapped.find(row=>String(row.id)===String(current.id))||null:current)};const refresh=async()=>{try{apply(await api.vehicles())}catch{setFleetLoaded(true)}};refresh().then(()=>{if(alive)stopStream=subscribeVehicles(apply)});timer=setInterval(refresh,30000);return()=>{alive=false;clearInterval(timer);stopStream()}},[authUser?.id,company?.id]);
  const setStore=(next)=>{if(!authUser){setToast('Sign in before saving school data.');return Promise.resolve(false)}const candidate={...next};const{vehicles,companies,users,...shared}=candidate;shared.companyProfile=companies?.[0]||{};const old={...store};delete old.vehicles;delete old.companies;delete old.users;old.companyProfile=store.companies?.[0]||{};const changed=Object.keys(shared).filter(key=>JSON.stringify(shared[key]??null)!==JSON.stringify(old[key]??null));const persist=async()=>{try{let savedState=shared,result;try{result=await api.saveCompanyState(savedState,version.current)}catch(error){if(error.status!==409)throw error;const latest=await api.companyState();if(!latest?.data||!Number.isFinite(Number(latest.version)))throw error;savedState={...latest.data};for(const key of changed)savedState[key]=shared[key];result=await api.saveCompanyState(savedState,Number(latest.version));}version.current=Number(result?.version)||version.current+1;const confirmed={...candidate,...savedState};const saved=saveStore(confirmed);setStoreRaw(saved);return true}catch{setToast('The server did not confirm this save. Refresh before retrying.');return false}};const queued=saveQueue.current.catch(()=>{}).then(persist);saveQueue.current=queued;return queued};
   const schoolPortalBase=window.location.hostname.toLowerCase()==='trackschoolbus.masar.qa'?'':'/schoolbus';
   const setPage=p=>{setPageRaw(p);const target=p==='dashboard'?(schoolPortalBase||'/'):`${schoolPortalBase}/${p}`;if(window.location.pathname!==target)window.history.pushState({},'',target);window.scrollTo(0,0)};
  useEffect(()=>{const onPop=()=>{const part=window.location.pathname.split('/').filter(Boolean).pop();setPageRaw(['children','buses','routes','branches','rfid','attenders','attendance','drivers','parents','coordinators','map','reports','settings'].includes(part)?part:'dashboard')};window.addEventListener('popstate',onPop);return()=>window.removeEventListener('popstate',onPop)},[]);
  const doLogout=async()=>{try{await api.logout()}catch{}setAuthToken('');setAuthUser(null)};
  if(!authChecked)return <BrandLoading label="Loading school portal"/>;
  if(!authUser)return <CompanyLogin company={company} onReady={hydrate}/>;
  const portalToast=x=>{setToast(x);setTimeout(()=>setToast(''),3500)};
  return <><SchoolPortalShell company={company} user={authUser} page={page} setPage={setPage} onLogout={doLogout}><SchoolPortalWorkspace page={page} company={company} store={store} setStore={setStore} toast={portalToast} setPage={setPage} user={authUser} fleetVehicles={fleetLoaded?fleetVehicles:undefined} fleetLoading={!fleetLoaded}/><Toast t={toast}/></SchoolPortalShell><ExportDialogHost/></>;
}

