  const [follow,setFollow]=useState(false);const markerRefs=useRef({});useEffect(()=>{if(selected?.id!=null&&layers.vehicles)markerRefs.current[String(selected.id)]?.openPopup()},[selected?.id]);
  useEffect(()=>{if(mapSelectionApplied.current||!vehicles.length)return;const saved=localStorage.getItem('inviha.schoolMapVehicleId');if(saved){const target=vehicles.find(v=>String(v.id)===String(saved));if(target){setSelected(target);setFollow(false)}}mapSelectionApplied.current=true},[vehicles,setSelected]);
  const [mapStyle,setMapStyle]=useState('');
